WITH recent_products AS (SELECT *, cost / NULLIF(stock_qty, 0) AS cost_per_stock_qty FROM products WHERE launch_date < '2025-03-23' OR brand NOT IN ('Acme', 'Stark', 'Umbrella')), products_stats AS (SELECT CASE WHEN stock_qty >= 388 THEN 'high' WHEN stock_qty >= 75 THEN 'mid' ELSE 'low' END AS stock_qty_bucket, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(brand))) AS brand_values FROM recent_products GROUP BY CASE WHEN stock_qty >= 388 THEN 'high' WHEN stock_qty >= 75 THEN 'mid' ELSE 'low' END) SELECT stock_qty_bucket, brand_values FROM products_stats;
